BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/jiuwudaishi-114-april-supply-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002709；EPUB电子本，纸本及异文待核", "id": "92b8127e-0098-5570-8c7d-6980ff4ebbef"}, {"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/jiuwudaishi-114-awards-northward-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002708；EPUB电子本，纸本及异文待核", "id": "c0ffdcba-8b59-5e3b-a81b-7ec4d2266a09"}, {"title": "宋史·巻二百七十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/songshi-273-li-qianpu-liaozhou/source.txt", "note": "《宋史》巻二百七十三，段落 songshi-9c6e46fee832-p059105；EPUB电子本，纸本及异文待核", "id": "68e0ab73-d396-574a-b04d-b53d85c7ac16"}, {"title": "资治通鉴·后周纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/tongjian-291-954-after-gaoping/source.txt", "note": "《资治通鉴》后周纪二，段落 zizhi-tongjian-a63549944a71-p003462；电子底本待考，分段待核", "id": "18677a75-3c75-5a95-9757-4db9054b227b"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/xinwudaishi-65-hongmiao-killed/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003289；EPUB电子本，纸本及异文待核", "id": "b1788e4f-5c0e-59d7-b61b-67b8965b61fc"}, {"title": "旧五代史·卷114·世宗本纪一·显德元年三月亲征", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/jiuwudaishi-114-campaign-march-954/source.txt", "note": "《旧五代史》卷114·世宗本纪一·显德元年三月亲征，段落 jiu-wudaishi-205deb4a7860-p002707；已核上下文及传主，纸本及异文待核。", "id": "a16cc231-7682-57f7-9978-41bf21405923"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/songshi-1-gaoping-counterattack/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000512；EPUB电子本，纸本及异文待核", "id": "446a6f67-6e42-561d-bd9e-7b5141a72cf7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "樊爱能", "aliases": ["樊愛能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周马军将领。954年正月获领武定节度使，旧纪同时记其军职与洋州节度职衔。生卒年暂未核定。", "biography": null, "status": "draft", "id": "31b12a36-803d-574a-a818-05742d936537"}, {"name": "何徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周虎捷指挥使。951年与王万敢、史彦超共同抵御北汉、契丹对晋州的进攻。生卒年未载。", "biography": null, "status": "draft", "id": "2982109b-18cc-561f-9927-a98ba7b7f5e6"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "史彦超（后周将领）", "aliases": ["史彦超", "史彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后周龙捷都指挥使。951年与王万敢、何徽防守晋州，抵抗北汉、契丹军。尚不与其他政权的同名将领合并，生卒年未录全。", "biography": null, "status": "draft", "id": "541b4701-1443-5a49-a822-4dc8d508ecee"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "马仁瑀", "aliases": ["馬仁瑀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "夏津人，后周内殿直。954年高平之战中骑马射敌，鼓舞士气；《宋史》马仁瑀传也记这次行动。生卒年本段未载。", "biography": null, "status": "draft", "id": "d2f479cf-a621-511c-8912-9bc00b29b68f"}, {"name": "马全乂", "aliases": ["馬全乂", "马全义", "馬全義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原为李守贞麾下骑士，后事柴荣。953年随柴荣入朝，郭威召见并任命为殿前指挥使，称赞其忠于所事。《宋史》作马全义，记同一河中经历、任职和召见言论，复用同人异名；后续生卒另待录。", "biography": null, "status": "draft", "id": "dac95b9c-875b-5289-a14d-87b438c324fb"}, {"name": "赵晁", "aliases": ["趙晁"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周控鹤都指挥使。954年三月向郑好谦表示宜慎重进军，郑转告柴荣后，两人被拘于怀州狱。生卒年未载。", "biography": null, "status": "draft", "id": "cd9622d4-b011-5634-b050-b6b748a36838"}, {"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "王得中", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上党人，北汉枢密直学士。951年九月受刘崇派遣出使契丹，祝贺新君即位，并请求援兵进攻晋州。生卒年未载。", "biography": null, "status": "draft", "id": "24fc3a64-54f4-5587-8e68-cf8c2b329c89"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "郭崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍卫马军都指挥使。952年郭威亲征兖州时，充在京都巡检。生卒年尚未录入。", "biography": null, "status": "draft", "id": "da797339-8eeb-5a3d-aa29-97f251a5943c"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "董希颜", "aliases": ["董希顏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉汾州防御使。954年四月王彦超进攻汾州时，董希颜以城向后周投降。《旧五代史》本纪及《新五代史》也记此事。生卒年未载。", "biography": null, "status": "draft", "id": "b0cf1fbb-bd6a-532e-839d-884e2f14500c"}, {"name": "康延沼", "aliases": ["康延昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年奉王峻之命，与陈思让等率骑兵追击北汉军。《宋史》陈思让传同役记康延昭，与陈思让分任左右厢排阵使，按同场同职对应；未与康延泽合并。生卒年未载。", "biography": null, "status": "draft", "id": "6f34d961-5d5f-50b2-9435-9f018039f0a8"}, {"name": "田琼", "aliases": ["田瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周密州防御使。954年四月奉柴荣之命进攻北汉沁州，未能攻下。此处沿用《通鉴》姓名；《旧五代史》此前密州防御使作田中，两名是否同人尚待校核。生卒年未载。", "biography": null, "status": "draft", "id": "2305aa69-3241-5942-bcdc-ab91dc9b143d"}, {"name": "李谦溥", "aliases": ["李謙溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周供备库副使。954年四月独自骑马说服辽州刺史投降后周。《宋史》也记同一职务与劝降行动，但把刺史姓名写作张乙，与《通鉴》张汉超不同。生卒年未载。", "biography": null, "status": "draft", "id": "ad5a349d-9360-5198-8d97-ba454f7202ae"}, {"name": "张汉超", "aliases": ["張漢超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉辽州刺史。954年四月接受后周供备库副使李谦溥的劝说，以城投降。《新五代史》《旧五代史》也记张汉超归顺，《宋史》同役写作张乙，暂不作为确定别名。生卒年未载。", "biography": null, "status": "draft", "id": "da6abfa2-0970-56f8-b8da-152410c2a4e1"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘邈", "aliases": ["劉弘邈", "刘洪邈", "劉洪邈"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘邈，获封王爵之子。", "biography": null, "status": "draft", "id": "163da583-4d97-5b02-8638-af9335014845"}, {"name": "林延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：林延遇，闽清宦者、国信事务受命者。", "biography": null, "status": "draft", "id": "b5a0d45a-e4ba-5230-bd2f-56bced660fbf"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}]'::jsonb)
